// The pane's state mark, moving on the surface's own frame clock so the pane
// need not redraw for it: at rest a dot, which does not move; the MiniDot
// spinner of charmbracelet/bubbles while a polish runs; its Points while a
// preview waits for an answer. A mark that does not move has no clock.
import type { ClientModule } from 'claude-code'

type Props = { kind: 'idle' | 'review' | 'busy'; color: string }
type Ref = { ticks: number; stop: (() => void) | null }
type State = { ref: Ref }

const TICK_MS = 100

// `hold` is how many ticks each frame stays up.
const MARKS = {
  idle: { hold: 1, frames: ['●'] },
  review: { hold: 2, frames: ['∙∙∙', '●∙∙', '∙●∙', '∙∙●'] },
  busy: { hold: 1, frames: ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏'] },
} as const

const Pulse: ClientModule<Props, State> = (props, surface) => {
  const { Text } = surface.elements
  const ref = surface.state?.ref ?? { ticks: 0, stop: null }
  const mark = MARKS[props.kind]
  const isMoving = mark.frames.length > 1

  // The clock starts when the mark moves, once, and stops when it comes to rest.
  if (isMoving && ref.stop === null) {
    ref.stop = surface.every(TICK_MS, () => {
      ref.ticks += 1
      surface.setState({ ref })
    })
    surface.setState({ ref })
  } else if (!isMoving && ref.stop !== null) {
    ref.stop()
    ref.stop = null
    ref.ticks = 0
  }

  const frame = Math.floor(ref.ticks / mark.hold) % mark.frames.length

  return (
    <Text color={props.color} bold>
      {mark.frames[frame]}
    </Text>
  )
}

export default Pulse

files.hooks/spinner.tsx:
// The pane's loading mark: a spinner and the time a polish has run, ticking on
// the surface's own frame clock so the pane need not redraw for it.
// `since` and `now` come from the hooks module's $.clock; between redraws it
// adds its own ticks.
import type { ClientModule } from 'claude-code'

type Props = { since: number; now: number; color: string }
type Ref = { base: number; ticks: number; lastNow: number }
type State = { ref: Ref }

const FRAMES = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏']
const TICK_MS = 100

const fmt = (ms: number): string => {
  const seconds = Math.max(0, Math.floor(ms / 1000))

  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`
}

const Spinner: ClientModule<Props, State> = (props, surface) => {
  const { Text } = surface.elements
  const ref = surface.state?.ref ?? { base: 0, ticks: 0, lastNow: -1 }

  if (props.now !== ref.lastNow) {
    // A fresh reading from the hooks module: restart the local count from it.
    ref.lastNow = props.now
    ref.base = props.now - props.since
    ref.ticks = 0
  }

  if (surface.state === undefined) {
    surface.setState({ ref })
    surface.every(TICK_MS, () => {
      ref.ticks += 1
      surface.setState({ ref })
    })
  }

  return (
    <Text color={props.color} bold>
      {`${FRAMES[ref.ticks % FRAMES.length]} ${fmt(ref.base + ref.ticks * TICK_MS)}`}
    </Text>
  )
}

export default Spinner

files.hooks/bar.tsx:
// The loading line: a short lit stretch that runs along a dotted track and comes
// round again for as long as a polish runs, on the surface's own frame clock.
// It says "working", never "this far along": a model call reports no progress,
// so nothing here fills up or counts down.
import type { ClientModule } from 'claude-code'

type Props = { width: number; color: string; dim: string }
type Ref = { ticks: number }
type State = { ref: Ref }

const TICK_MS = 45
const LIT = 6
// Dots, not a line: the rule under the pane's heading is a line, and the two
// stand one above the other.
const TRACK = '·'

const Bar: ClientModule<Props, State> = (props, surface) => {
  const { Text } = surface.elements
  const ref = surface.state?.ref ?? { ticks: 0 }

  if (surface.state === undefined) {
    surface.setState({ ref })
    surface.every(TICK_MS, () => {
      ref.ticks += 1
      surface.setState({ ref })
    })
  }

  const width = Math.max(LIT + 2, Math.floor(props.width))
  // The stretch enters at the left edge, leaves at the right, and enters again.
  const head = (ref.ticks % (width + LIT)) - LIT
  const from = Math.max(0, head)
  const to = Math.min(width, head + LIT)

  return (
    <Text>
      <Text color={props.dim}>{TRACK.repeat(from)}</Text>
      <Text color={props.color}>{'━'.repeat(Math.max(0, to - from))}</Text>
      <Text color={props.dim}>{TRACK.repeat(width - to)}</Text>
    </Text>
  )
}

export default Bar

